const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  chat:'M4 4h16v12H9l-5 4V4Z',draft:'M5 3h10l4 4v14H5V3Zm10 0v5h4M8 12h8M8 16h5',agent:'M8 6V4m8 2V4M5 8h14v12H5V8Zm4 5h.01M15 13h.01M9 17h6M2 12v4m20-4v4M10 4h4',settings:'m9 3-.6 3-2 .9-2.7-.8-2 3.5L4 11v2l-2.3 1.4 2 3.5 2.7-.8 2 .9.6 3h4l.6-3 2-.9 2.7.8 2-3.5L18 13v-2l2.3-1.4-2-3.5-2.7.8-2-.9L13 3H9ZM11 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',switcher:'m9 8 3-3 3 3m-6 8 3 3 3-3',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',more:'M5 12h.01M12 12h.01M19 12h.01',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',send:'m3 3 19 9-19 9 4-9-4-9Zm4 9h15',spark:'m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3L12 3Zm7-2 .6 1.4L21 3l-1.4.6L19 5l-.6-1.4L17 3l1.4-.6L19 1',refresh:'M20 7V3l-3 3a8 8 0 1 0 2.3 9M20 3h-4',edit:'m14 4 6 6M4 20l4-1 13-13-4-4L4 15v5Z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',warning:'m12 3 10 18H2L12 3Zm0 6v5m0 3h.01',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 8v6m0-10h.01',panel:'M3 4h18v16H3V4Zm12 0v16',external:'M13 3h8v8m0-8L10 14M9 3H3v18h18v-6',copy:'M8 8h13v13H8V8ZM16 8V3H3v13h5',link:'m10 7 2-2a5 5 0 0 1 7 7l-2 2m-3 3-2 2a5 5 0 0 1-7-7l2-2m1 6 8-8',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M2 21v-3a7 7 0 0 1 14 0v3m1-17a4 4 0 0 1 0 8m2 3a6 6 0 0 1 3 6',building:'M4 21V3h11v18M15 10h5v11M8 7h3M8 11h3M8 15h3M8 21v-3h3v3',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 9 3 3 5-6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',filter:'M4 6h16M7 12h10m-7 6h4',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3V4Zm9 2v16',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',key:'M8 3a5 5 0 1 0 0 10 5 5 0 0 0 0-10m4 8 9 9m-4-4 3-3m-6 0 3-3',pause:'M8 5v14M16 5v14',play:'m7 3 14 9-14 9V3Z',logout:'M10 3H3v18h7m5-14 5 5-5 5M8 12h12',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10m0-5v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',inbox:'M5 3h14l3 12v6H2v-6L5 3ZM2 15h6l2 3h4l2-3h6',layers:'m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5'
};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.info}"/></svg>`;
const btn = (label,action,cls='',ic='',extra='') => `<button class="btn ${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${label}</button>`;
const ibtn = (label,action,ic,cls='ghost') => btn('',action,`${cls} icon-only`,ic,`aria-label="${esc(label)}" title="${esc(label)}"`);
const badge = (label,color='')=>`<span class="pill ${color}">${label}</span>`;
const av = (initials,color='',large='')=>`<span class="avatar ${color} ${large}">${initials}</span>`;
const spark = ()=>`<span class="sparkbox">${icon('spark')}</span>`;
const blank = (title,copy,action='',label='',ic='inbox')=>`<div class="empty"><div class="empty-icon">${icon(ic)}</div><h2>${title}</h2><p>${copy}</p>${action?btn(label,action,'primary'):''}</div>`;
const notice = (title,copy,type='',action='',label='')=>`<div class="notice ${type}">${icon(type==='error'?'warning':type==='success'?'check':'info')}<div><strong>${title}</strong>${copy}${action?'<div>'+btn(label,action,'small')+'</div>':''}</div></div>`;
const fixtures = [
 {id:'elena',name:'Elena Morozova',initials:'EM',company:'Northstar Labs',position:'VP Marketing',industry:'B2B SaaS',color:'',time:'2 min',status:'ready',labels:['Interested','Information Request'],incoming:'Please do. Could you share the most relevant B2B SaaS examples and an indication of pricing for a team our size?',draft:'Hi Elena — absolutely. I can share a couple of relevant B2B SaaS examples and walk you through pricing for your team. How many people would be using the inbox?',campaign:'SaaS Leaders — Q3'},
 {id:'marcus',name:'Marcus Chen',initials:'MC',company:'Pilotly',position:'Head of Growth',industry:'Software',color:'purple',time:'18 min',status:'ready',labels:['Meeting Request'],incoming:'This is timely. Could we find 20 minutes next Tuesday or Wednesday to walk through it?',draft:'Hi Marcus — happy to walk you through it. Would Tuesday at 2 pm work for you? I can send a calendar invite once you confirm your time zone.',campaign:'SaaS Leaders — Q3'},
 {id:'priya',name:'Priya Nair',initials:'PN',company:'Northstar Growth Partners',position:'COO',industry:'Growth consultancy',color:'teal',time:'43 min',status:'needs',labels:['Information Request'],incoming:'Can you share how pricing changes with multiple LinkedIn senders and whether onboarding is included?',draft:'',campaign:'Founder Network'},
 {id:'owen',name:'Owen Brooks',initials:'OB',company:'Nola',position:'Founder',industry:'Design services',color:'amber',time:'1 hr',status:'ready',labels:['Referral'],incoming:"I'm not the right person, but Sofia runs outbound here — happy to point you her way.",draft:'Thanks, Owen — an introduction to Sofia would be very helpful. Happy to give her a brief overview of how this could fit your outbound process.',campaign:'Agency Leaders'},
 {id:'daniel',name:'Daniel Weber',initials:'DW',company:'Pilotly',position:'Sales Director',industry:'Software',color:'teal',time:'3 hr',status:'ready',labels:['Interested','Information Request'],incoming:'Interesting approach — do you support German-language replies and shared team inboxes?',draft:'Hi Daniel — yes, your team can work from a shared inbox and prepare replies in German. Would you like to see how the review workflow works?',campaign:'SaaS Leaders — Q3'},
 {id:'sophie',name:'Sophie Laurent',initials:'SL',company:'Northstar Growth Partners',position:'Operations Lead',industry:'Consulting',color:'pink',time:'4 hr',status:'needs',labels:['Information Request'],incoming:'Could you send the security overview and confirm your data retention policy before I involve our operations team?',draft:'',campaign:'Founder Network'},
 {id:'maya',name:'Maya Thompson',initials:'MT',company:'Brightside',position:'Founder',industry:'Client services',color:'purple',time:'Tomorrow',status:'later',labels:['Meeting Request'],incoming:"Thursday afternoon works best. Could you check back tomorrow once I have my calendar?",draft:'Hi Maya — following up as promised. Does Thursday at 3 pm still work for a short walkthrough?',campaign:'Agency Leaders'},
 {id:'anna',name:'Anna Sokolova',initials:'AS',company:'Kontur',position:'Head of Sales',industry:'Technology',color:'',time:'Monday',status:'later',labels:['Interested'],incoming:'This sounds useful. Let me discuss it with the team and get back to you next week.',draft:'Hi Anna — happy to answer any questions after you speak with the team.',campaign:'Founder Network'}
];
let items = structuredClone(fixtures);
let state = {page:'drafts',scene:'ready',selected:'elena',queue:'ready',details:innerWidth>1180,mode:'draft',query:'',workspace:'Aster',editorStep:'basics',agentFilter:'all',agentView:'grid',draftText:'',manualText:'',redraftText:'',mobileThread:false,sent:[],catalog:false,modal:null,setting:'general',setupStep:'name',setupName:'Restaff',setupKey:'hr_demo_workspace_key',importDays:7,inviteEmail:'',notes:'',agentName:'Reply Handler — Fintech Q3',objective:'call',language:'English',replyLogic:'Only positive',followups:false,settingsSaved:false};
const labels = xs=>xs.map(x=>badge(x,{'Interested':'green','Information Request':'blue','Meeting Request':'purple','Referral':'amber'}[x]||'')).join(' ');
function selected(){return items.find(i=>i.id===state.selected)||fixtures[0]}
function navigate(route){state.modal=null;state.catalog=false;if(location.hash==='#/'+route){readRoute();render()}else location.hash='/'+route}
function readRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/');state.page=parts[0]||'drafts';state.scene=parts[1]||({drafts:'ready',settings:'general',setup:'name',agents:'list',conversations:'list'}[state.page]);state.mode='draft';state.query='';state.mobileThread=false;state.details=innerWidth>1180;state.setting=state.scene;state.setupStep=state.scene;if(state.page==='drafts'){state.queue=state.scene==='needs-input'?'needs':state.scene==='snoozed'?'later':'ready';state.selected=state.queue==='needs'?'priya':state.queue==='later'?'maya':'elena';if(['manual','edit','redraft'].includes(state.scene))state.mode=state.scene;state.draftText=selected().draft;}if(state.page==='agents'&&['basics','knowledge','followups','test','launch'].includes(state.scene))state.editorStep=state.scene;document.title=`Aster — ${state.page==='setup'?'New workspace':state.page[0].toUpperCase()+state.page.slice(1)} · Design`}
function sidebar(){return `<aside class="sidebar"><button class="workspace-button" data-action="workspaces" aria-label="Switch workspace"><span class="brandmark">${state.workspace==='Aster'?'AS':'RE'}</span><span class="grow"><strong>${esc(state.workspace)}</strong><small>Workspace</small></span>${icon('switcher')}</button><nav class="nav" aria-label="Main navigation">${[['conversations','Conversations','chat'],['drafts','Drafts','draft'],['agents','Agents','agent'],['settings','Settings','settings']].map(([id,label,ic])=>`<button aria-label="${label}" class="nav-item ${state.page===id?'active':''}" data-action="nav:${id}">${icon(ic)}<span>${label}</span>${id==='drafts'?'<span class="nav-count purple">'+(state.page==='drafts'&&state.scene==='empty'?0:items.filter(x=>['ready','needs'].includes(x.status)).length)+'</span>':''}</button>`).join('')}</nav><div class="sidebar-spacer"></div><button class="preview-trigger" data-action="catalog" title="Screen catalogue">${icon('layers')}<span>Design preview</span></button><button class="user-button" data-action="profile">${av('IL')}<span class="grow"><strong>Ivan Leushin</strong><small>Owner</small></span>${icon('more')}</button></aside>`}
function topbar(title,extra=''){return `<header class="topbar">${title?`<h1>${title}</h1><div class="grow"></div>`:""}${extra}</header>`}
function threadMessages(person){return `<div class="thread-content"><div class="date-divider">Monday, September 7</div><div class="message outbound"><div class="message-meta">${av('JR','purple')}<span>John Richardson</span><time>10:14 am</time></div><div class="bubble">Hi ${person.name.split(' ')[0]} — I noticed ${esc(person.company)} is growing its outbound team. We help teams handle LinkedIn replies and keep every conversation moving. Would it be useful to compare notes?</div></div>${person.id==='elena'?`<div class="message"><div class="message-meta">${av(person.initials,person.color)}<span>${person.name}</span><time>11:02 am</time></div><div class="bubble">Hi John, yes, this could be relevant. We're reviewing how to scale outbound while keeping the messaging personal.</div></div><div class="message outbound"><div class="message-meta">${av('JR','purple')}<span>John Richardson</span><time>11:08 am</time></div><div class="bubble">That makes sense. I can share a few examples from similar B2B SaaS teams and a simple pricing overview.</div></div>`:''}<div class="date-divider">Today</div><div class="message"><div class="message-meta">${av(person.initials,person.color)}<span>${person.name}</span><time>${person.time} ago</time></div><div class="bubble">${esc(person.incoming)}</div></div>${state.scene==='stale'?`<div class="message"><div class="message-meta">${av(person.initials,person.color)}<span>${person.name}</span><time>Just now</time></div><div class="bubble">One more thing — can we include our agency partners in the same workspace?</div></div>`:''}${state.sent.filter(x=>x.person===person.id).map(x=>`<div class="message outbound success"><div class="message-meta">${av('JR','purple')}<span>John Richardson</span><time>Now</time></div><div class="bubble">${esc(x.body)}<span class="sent">✓ Sent</span></div></div>`).join('')}</div>`}
function contextPanel(person){return `<aside class="context" aria-label="Lead context"><div class="context-profile"><div class="row between">${av(person.initials,person.color,'large')}${ibtn('Close details','toggle-details','close')}</div><h2>${person.name}</h2><p>${person.position} at ${person.company}</p><button class="link-btn small" style="margin-top:12px" data-action="linkedin">LinkedIn profile ${icon('external')}</button></div><div class="context-section"><p class="eyebrow">Lead details</p><div class="details-row"><span>Company</span><span>${person.company}</span></div><div class="details-row"><span>Industry</span><span>${person.industry}</span></div><div class="details-row"><span>Language</span><span>English</span></div></div><div class="context-section"><p class="eyebrow">Conversation</p><div class="details-row"><span>Campaign</span><span>${person.campaign}</span></div><div class="details-row"><span>Sender</span><span>John Richardson</span></div><div class="details-row"><span>Labels</span><span style="display:flex;gap:5px;flex-wrap:wrap">${labels(person.labels)}</span></div></div><div class="context-section"><p class="eyebrow">Assigned agent</p><button class="agent-link" data-action="agent-open">${spark()}<span class="grow"><strong>Reply Handler — Fintech Q3</strong><small><span class="dot" style="color:var(--green)"></span> Active · approval required</small></span>${icon('chevron')}</button></div><div class="context-section"><p class="eyebrow">Notes</p><textarea style="min-height:85px;font-size:12px" data-input="notes" placeholder="Add a note for your team…">${esc(state.notes)}</textarea></div></aside>`}
function composer(person){const mode=state.mode, scene=state.scene;let content='';if(person.status==='needs'&&mode!=='manual'){content=`<div class="composer-title"><span class="sparkbox" style="color:var(--amber);background:#392e1d">${icon('book')}</span>Needs your input</div><p class="draft-text">The agent needs an approved answer before it can draft a reply.</p><div class="notice" style="margin-top:14px"><div><strong>${person.id==='sophie'?'Data retention and security documentation':'Pricing for multiple senders'}</strong>${person.id==='sophie'?'No approved security overview or retention policy was found.':'Your Knowledge does not say how additional senders are priced or whether onboarding is included.'}</div></div><div class="field" style="margin-top:16px;margin-bottom:0"><label for="answer-input">Your answer</label><textarea id="answer-input" data-input="answer" placeholder="Add the details the agent can use…">${esc(state.answer||'')}</textarea><label class="row small muted" style="font-weight:400"><input type="checkbox" data-input="remember" ${state.remember?'checked':''}> Save this answer to the agent’s Knowledge</label></div><div class="composer-actions">${btn('Reply manually','manual','ghost')}<div class="row">${ibtn('Snooze','snooze','clock')}${btn('Generate draft','answer-generate','primary','spark',state.answer?'':'disabled')}</div></div>`}
else if(scene==='sending'||mode==='sending'){content=`<div class="composer-title">${spark()}Sending…</div><p class="draft-text">${esc(state.draftText||person.draft)}</p><div class="composer-actions"><span class="small muted">Sending as John Richardson</span>${btn('Sending…','noop','primary','','disabled')}</div>`}
else if(scene==='unknown'){content=`<div class="composer-title">${icon('warning')}Send status unavailable</div><p class="draft-text">${esc(person.draft)}</p><div style="margin-top:15px">${notice('We did not receive a response','The message may have been sent. Check its status before sending it again.','', 'check-send','Check status')}</div><div class="composer-foot"><span>John Richardson → ${person.name}</span><span>Saved</span></div>`}
else if(mode==='generating'||scene==='generating'){content=`<div class="composer-title">${spark()}Preparing a new draft</div><div class="skeleton wide"></div><div class="skeleton wide"></div><div class="skeleton medium"></div><div class="composer-actions"><span class="small muted">Using this conversation and your Knowledge</span>${btn('Cancel','cancel-generation','ghost')}</div>`}
else if(mode==='redraft'){content=`<div class="composer-title">${spark()}Redraft with instructions</div><textarea data-input="redraftText" placeholder="What should change? For example, make it shorter and offer a demo.">${esc(state.redraftText)}</textarea><div class="composer-actions"><span class="small muted">Current draft included</span><div class="row">${btn('Cancel','cancel-edit','ghost')}${btn('Generate draft','redraft-generate','primary','spark',state.redraftText?'':'disabled')}</div></div>`}
else if(mode==='manual'){content=`<textarea data-input="manualText" placeholder="Write a message…" aria-label="Message">${esc(state.manualText)}</textarea><div class="composer-actions"><span class="small muted">Sending as John Richardson</span><div class="row">${btn('Draft','generate','ghost','spark')}${btn('Send','send','primary','send',state.manualText.trim()?'':'disabled')}</div></div>`}
else {content=`<div class="composer-title">${spark()}${mode==='edit'?'Editing draft':'AI draft'}<span class="version">${scene==='stale'?'Update needed':mode==='edit'?'Changes saved':'Ready for review'}</span></div>${scene==='stale'?notice('A new reply arrived','Review the latest message, then update this draft.','info','update-draft','Update draft'):''}${mode==='edit'?`<textarea data-input="draftText" aria-label="Edit draft">${esc(state.draftText||person.draft)}</textarea>`:`<p class="draft-text" style="${scene==='stale'?'margin-top:14px;color:var(--muted)':''}">${esc(state.draftText||person.draft)}</p>`}${scene==='send-error'?'<div style="margin-top:14px">'+notice('Message was not sent','HeyReach rejected this attempt. Your reply is saved. You can try again.','error')+'</div>':''}<div class="composer-actions">${mode==='edit'?btn('Cancel','cancel-edit','ghost'):btn('Reply manually','manual','ghost')}<div class="row">${mode!=='edit'?ibtn('More draft actions','draft-more','more'):''}${mode!=='edit'?btn('Edit','edit'):''}${mode!=='edit'?btn('Redraft','redraft'):''}${btn(scene==='send-error'?'Try again':'Send','send','primary','',scene==='stale'?'disabled':'')}</div></div>`}
return `<div class="composer-wrap"><div class="composer ${person.status==='needs'&&mode!=='manual'?'needs-input':''}">${content}</div>${state.page==='drafts'&&!['empty','unknown','sending'].includes(scene)?'<div class="composer-foot" style="max-width:740px;margin-left:auto;margin-right:auto"><span>Review, send, and move to the next conversation</span><span>⌘ Enter to send</span></div>':''}</div>`}
function thread(person){return `<section class="thread"><header class="thread-header">${ibtn('Back to queue','back-queue','back','ghost mobile-only')}${av(person.initials,person.color)}<div class="grow"><h2>${person.name}</h2><p>${person.company} · ${person.status==='later'?'Snoozed until '+person.time:'Replied '+person.time+' ago'}</p></div>${ibtn('Snooze draft','snooze','clock')}${ibtn('Show lead details','toggle-details','panel')}</header><div class="thread-scroll">${threadMessages(person)}</div>${composer(person)}</section>`}
function draftScreen(){let visible=items.filter(x=>x.status===state.queue&&(!state.query||(x.name+' '+x.company).toLowerCase().includes(state.query.toLowerCase())));if(state.scene==='empty')return topbar('Drafts')+blank('You’re all caught up','New drafts will appear here when a lead replies. You can browse all conversations in the meantime.','nav:conversations','View conversations','check');if(state.scene==='error')return topbar('Drafts')+blank('Drafts could not be loaded','Your conversations and saved replies are safe. Try loading the queue again.','retry-drafts','Try again','warning');const loading=state.scene==='loading';if(!visible.some(x=>x.id===state.selected)&&visible.length)state.selected=visible[0].id;const p=selected();return topbar('Drafts',`<span class="small muted">${items.filter(x=>['ready','needs'].includes(x.status)).length} to review</span>${ibtn('Refresh drafts','refresh-drafts','refresh')}`)+`<div class="draft-layout ${state.details?'':'details-closed'} ${state.mobileThread?'mobile-thread':''}"><aside class="queue"><div class="queue-head"><div class="tabs">${[['ready','Ready'],['needs','Needs input'],['later','Later']].map(([key,label])=>`<button class="tab ${state.queue===key?'active':''}" data-action="queue:${key}">${label}<span class="num">${items.filter(x=>x.status===key).length}</span></button>`).join('')}</div><label class="search">${icon('search')}<input placeholder="Search drafts…" aria-label="Search drafts" data-input="query" value="${esc(state.query)}"></label></div><div class="queue-list">${loading?Array.from({length:5},()=>'<div class="skeleton-box"><div class="skeleton medium"></div><div class="skeleton wide"></div><div class="skeleton short"></div></div>').join(''):visible.map(x=>`<button class="queue-item ${x.id===state.selected?'selected':''}" data-action="select:${x.id}"><span class="row">${av(x.initials,x.color)}<span class="grow"><span class="name">${x.name}</span><span class="company" style="display:block">${x.company}</span></span><span class="time">${x.time}</span></span><span class="snippet">${x.incoming}</span><span class="queue-status ${x.status==='needs'?'warning':''}">${icon(x.status==='needs'?'book':x.status==='later'?'clock':'spark')}<span>${x.status==='needs'?'Needs your input':x.status==='later'?'Snoozed until '+x.time:'Draft ready'}</span></span></button>`).join('')||'<div class="empty" style="min-height:200px;padding:20px"><h3>No drafts here</h3><p style="font-size:12px">'+(state.query?'Try another name or company.':'New items will appear in this queue.')+'</p></div>'}</div><div class="queue-footer"><span>Newest replies first</span><span>${visible.length} conversations</span></div></aside>${loading?`<section class="thread"><div class="thread-header"><div class="skeleton medium"></div></div><div class="thread-scroll"><div class="skeleton-box"><div class="skeleton wide"></div><div class="skeleton wide"></div><div class="skeleton medium"></div></div></div></section>`:visible.length?thread(p):blank('Queue cleared','Choose another queue or come back when new drafts arrive.','','','check')}${state.details&&visible.length&&!loading?contextPanel(p):''}</div>`}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function render(){if(state.page==='auth'){$('#app').innerHTML=authScreen();renderOverlay();return;}const pages={drafts:draftScreen,settings:settingsScreen,setup:setupScreen,agents:agentsScreen,conversations:conversationsScreen};$('#app').innerHTML=`<div class="shell">${sidebar()}<main class="workspace-main">${(pages[state.page]||draftScreen)()}</main></div>`;renderOverlay();const transcript=$('.thread-scroll');if(transcript)transcript.scrollTop=transcript.scrollHeight;}
function field(label,content,help=''){return `<div class="field"><label>${label}</label>${content}${help?`<p class="help">${help}</p>`:''}</div>`}
function toggle(label,key,value){return `<button class="switch ${value?'on':''}" role="switch" aria-label="${label}" aria-checked="${!!value}" data-action="toggle:${key}"></button>`}
function accountList(){return `<div class="account-line">${av('JR','purple')}<div class="grow"><strong>John Richardson</strong><br><small>LinkedIn account</small></div>${badge('Connected','green')}</div><div class="account-line">${av('SW','teal')}<div class="grow"><strong>Sarah Wilson</strong><br><small>LinkedIn account</small></div>${badge('Connected','green')}</div><div class="account-line">${av('DK','amber')}<div class="grow"><strong>Daniel Klein</strong><br><small>LinkedIn account</small></div>${badge('Reconnect','amber')}</div>`}
function importCard(scene='import'){const running=scene==='import-running',done=scene==='import-done',error=scene==='import-error';return `<div class="card"><div class="card-header"><div class="row">${icon('download')}<h2>Import conversation history</h2></div>${running?badge('In progress','purple'):done?badge('Complete','green'):error?badge('Paused','amber'):''}</div><p class="muted">Bring past conversations into your inbox and classify the latest replies.</p>${running||done||error?`<div class="row between" style="margin-top:25px"><h3>Last ${state.importDays} days</h3><span class="small muted">${done?'Finished just now':error?'Connection interrupted':'About 2 minutes remaining'}</span></div><div class="progress"><span style="width:${done?'100':error?'48':'64'}%"></span></div><div class="stats"><div class="stat"><strong>${done?'146':error?'70':'94'}</strong><span>Conversations imported</span></div><div class="stat"><strong>${done?'812':error?'390':'523'}</strong><span>Messages</span></div><div class="stat"><strong>${done?'146':error?'62':'89'}</strong><span>Conversations classified</span></div></div>${error?notice('The import stopped before it finished','Already imported conversations are saved. Reconnect HeyReach, then resume from where you left off.','','resume-import','Reconnect and resume'):done?notice('Your history is ready','Existing conversations were classified. Historical messages did not create a draft queue.','success'):notice('You can leave this page','The import will continue in the background. New incoming replies are still received.','info')}<div class="row" style="justify-content:flex-end;margin-top:20px">${done?btn('View conversations','nav:conversations','primary'):running?btn('Pause import','pause-import','ghost'):''}</div>`:`<div class="field" style="margin-top:23px"><label>History window</label><div class="row" style="flex-wrap:wrap">${[7,14,30,90].map(n=>btn(n+' days','days:'+n,state.importDays===n?'primary':'')).join('')}</div></div><div class="notice info">${icon('info')}<div>History is imported and classified. Drafts are prepared for new replies after your agent is active.</div></div><div class="row" style="justify-content:flex-end;margin-top:24px">${btn('Start import','start-import','primary','download')}</div>`}</div>`}
function webhookContent(waiting=false){return `<div class="row between" style="margin-bottom:14px"><div><h3>Incoming replies</h3><p class="muted small" style="margin-top:5px">${waiting?'Webhook configured. Waiting for the first event.':'Receiving new replies from HeyReach.'}</p></div>${badge(waiting?'Waiting for event':'Receiving events',waiting?'amber':'green')}</div>${waiting?notice('No incoming reply yet','This is normal if nobody has replied since setup. You can continue using the workspace.','','simulate-event','Check for an event'):`<div class="row small muted">${icon('check')}Last event received 2 minutes ago</div>`}<div class="code-box"><code>https://hooks.aster.example/inbound/wh_demo_••••••••</code>${ibtn('Copy webhook URL','copy-webhook','copy')}</div><div class="row between"><span class="small muted">Listening for message replies</span>${btn('Setup instructions','webhook-help','ghost small')}</div>`}
function connectionCard(scene){const missing=scene==='disconnected',bad=scene==='key-error',waiting=scene==='webhook-waiting';return `<div class="card"><div class="card-header"><div class="row"><span class="brandmark" style="background:#ef6138">H</span><div><h2>HeyReach</h2><p class="small muted">LinkedIn messaging</p></div></div>${badge(missing?'Not connected':bad?'Needs attention':'Connected',missing?'':bad?'amber':'green')}</div>${missing?`<p class="muted">Connect a HeyReach workspace to receive conversations and send approved replies.</p><div style="margin-top:22px">${btn('Connect HeyReach','connect-existing','primary','link')}</div>`:bad?`${notice('Your API key is no longer valid','New messages cannot sync and sending is paused. Your conversations and drafts are saved.','error')}<div class="field" style="margin-top:20px"><label>Replacement API key</label><input type="password" value="hr_demo_workspace_key" aria-label="Replacement API key"></div><div style="text-align:right">${btn('Verify and reconnect','verify-reconnect','primary')}</div>`:`<div class="setting-row"><div><h3>${state.workspace} · HeyReach workspace</h3><p>Connected by Ivan Leushin</p></div>${btn('Test connection','test-connection','small')}</div><div class="setting-row"><div><h3>API key</h3><p>••••••••••••••••7f2a</p></div>${btn('Replace key','replace-key','ghost small')}</div><div class="divider"></div>${webhookContent(waiting)}<div class="divider"></div><div class="row between" style="margin-bottom:14px"><h3>Sender accounts</h3><span class="small muted">3 accounts</span></div>${accountList()}<p class="small muted" style="margin-top:13px">Sender accounts and campaigns come from this HeyReach workspace.</p><div class="divider"></div><div class="row between"><span class="small muted">Last synced 2 minutes ago</span>${btn('Disconnect','disconnect','ghost small')}</div>`}</div>`}
function settingsScreen(){const connectionScenes=['connection','disconnected','key-error','webhook-waiting','import','import-running','import-done','import-error'];const tab=connectionScenes.includes(state.scene)?'connection':state.scene;let content='';
if(tab==='general')content=`<div class="section-intro"><h1>General</h1><p class="page-description">Manage your workspace identity and defaults.</p></div><div class="card"><div class="row" style="margin-bottom:25px"><span class="brandmark" style="width:48px;height:48px;font-size:16px">${state.workspace.slice(0,2).toUpperCase()}</span><div><h3>Workspace icon</h3><p class="muted small">Initials are used until you add an image.</p></div>${btn('Change','workspace-icon','ghost small','','style="margin-left:auto"')}</div>${field('Workspace name',`<input aria-label="Workspace name" data-input="workspaceName" value="${esc(state.workspaceName||state.workspace)}">`)}${field('Workspace URL','<div class="row"><span class="muted small">app.aster.example/</span><input value="aster" aria-label="Workspace URL" style="flex:1"></div>')}${field('Time zone','<select aria-label="Time zone"><option>Europe / Moscow (UTC+3)</option>Europe / London</option>America / New York</option></select>','Used for snoozed drafts and activity timestamps.')}<div style="text-align:right">${btn('Save changes','save-settings','primary')}</div></div><div class="card" style="margin-top:20px"><div class="setting-row"><div><h3>Pause AI drafting</h3><p>Keep receiving messages and replying manually.</p></div>${toggle('Pause AI drafting','aiPaused',state.aiPaused)}</div></div><div style="margin-top:27px"><button class="link-btn" style="color:var(--muted);font-size:12px" data-action="archive-workspace">Archive workspace</button></div>`;
else if(tab==='connection'){content=`<div class="section-intro"><h1>HeyReach connection</h1><p class="page-description">Receive conversations and send replies from your existing accounts.</p></div><div class="stack">${['import','import-running','import-done','import-error'].includes(state.scene)?importCard(state.scene):connectionCard(state.scene)}${['connection','webhook-waiting'].includes(state.scene)?`<div class="card"><div class="row between"><div><h3>Conversation history</h3><p class="muted" style="margin-top:6px">Import past conversations from HeyReach.</p></div>${btn('Import history','scene:settings/import','small','download')}</div></div>`:''}</div>`}
else if(tab==='members')content=`<div class="section-intro row between"><div><h1>Members</h1><p class="page-description">Choose who can access ${esc(state.workspace)}.</p></div>${btn('Invite member','invite','primary','plus')}</div><div class="card" style="padding:0 20px"><div class="account-line" style="border-top:0;padding:20px 0">${av('IL')}<div class="grow"><strong>Ivan Leushin <span class="muted">(you)</span></strong><br><small>ivan@example.com</small></div>${badge('Owner')}</div><div class="account-line" style="padding:20px 0">${av('AC','teal')}<div class="grow"><strong>Alex Carter</strong><br><small>alex@example.com</small></div><select aria-label="Alex’s role" data-input="alexRole" style="font-size:12px;padding:6px"><option>Member</option><option>Admin</option></select>${ibtn('Member actions','member-actions','more')}</div>${state.invited?`<div class="account-line" style="padding:20px 0">${av('IN','purple')}<div class="grow"><strong>${esc(state.invited)}</strong><br><small>Invitation pending</small></div>${badge('Invited','purple')}${btn('Revoke','revoke-invite','ghost small')}</div>`:''}</div><div class="card" style="margin-top:22px"><h3 style="margin-bottom:15px">Workspace roles</h3><div class="details-row" style="grid-template-columns:70px 1fr"><span>Owner</span><span class="muted">Manage the workspace, members and all settings.</span></div><div class="details-row" style="grid-template-columns:70px 1fr"><span>Admin</span><span class="muted">Manage agents, connections and team access.</span></div><div class="details-row" style="grid-template-columns:70px 1fr"><span>Member</span><span class="muted">Review drafts, send replies and manage conversations.</span></div></div>`;
else content=`<div class="section-intro"><h1>Preferences</h1><p class="page-description">Personal settings for how you work through your inbox.</p></div><div class="card"><div class="setting-row"><div><h3>Open the next draft after sending</h3><p>Keep moving through the review queue.</p></div>${toggle('Open next draft','autoNext',state.autoNext!==false)}</div><div class="setting-row"><div><h3>Show lead details by default</h3><p>Keep the contact panel open on wide screens.</p></div>${toggle('Show lead details','defaultDetails',state.defaultDetails!==false)}</div><div class="setting-row"><div><h3>Keyboard shortcuts</h3><p>Send with ⌘ Enter. Close a dialog with Escape.</p></div>${toggle('Keyboard shortcuts','shortcuts',state.shortcuts!==false)}</div></div><div class="card" style="margin-top:20px"><h3 style="margin-bottom:20px">Appearance</h3><div class="row between"><span class="small muted">Theme</span><span class="pill">Dark</span></div></div>`;
return topbar('Settings')+`<div class="content-scroll"><div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${[['general','General','building'],['connection','HeyReach','link'],['members','Members','users'],['preferences','Preferences','settings']].map(([id,title,ic])=>`<button class="settings-tab ${tab===id?'active':''}" data-action="scene:settings/${id}">${icon(ic)}${title}</button>`).join('')}</nav><section>${content}</section></div></div>`}
function setupScreen(){let step=state.scene==='key-error'?'connect':state.scene;const steps=['name','connect','webhook','import','agent'],index=steps.indexOf(step);let content='';const next=(label,to)=>`<div class="wizard-footer">${btn(index>0?'Back':'Cancel',index>0?'setup-back':'nav:drafts','ghost')}${btn(label,to,'primary','arrow')}</div>`;
if(step==='name')content=`<h1>Create a workspace</h1><p class="page-description">A dedicated inbox, agents and HeyReach connection for one team or client.</p>${field('Workspace name',`<input aria-label="New workspace name" data-input="setupName" value="${esc(state.setupName)}" placeholder="e.g. Restaff">`,'You can change this later.')}${field('Time zone','<select aria-label="New workspace time zone"><option>Europe / Moscow (UTC+3)</option>Europe / London</option><option>America / New York</option></select>')}<div class="notice info">${icon('users')}<div>You’ll be the workspace owner. You can invite teammates after setup.</div></div>${next('Continue','setup-next')}`;
if(step==='connect')content=`<h1>Connect HeyReach</h1><p class="page-description">Use the API key for the HeyReach workspace you want to connect to ${esc(state.setupName)}.</p><div class="card"><div class="row" style="margin-bottom:24px"><span class="brandmark" style="background:#ef6138;width:38px;height:38px;font-size:17px">H</span><div><h2>HeyReach</h2><p class="muted small">Conversations, campaigns and sender accounts</p></div></div>${field('Workspace API key',`<input type="password" aria-label="HeyReach workspace API key" data-input="setupKey" value="${esc(state.setupKey)}" autocomplete="off">`,'Find your workspace API key in HeyReach settings.')}${state.scene==='key-error'?notice('This API key could not be verified','Check that you copied the complete key for the correct HeyReach workspace.','error'):''}<div class="row small muted" style="margin-top:18px;align-items:flex-start">${icon('shield')}<span>Your key is used only for this workspace.</span></div></div>${next('Verify connection','verify-key')}`;
if(step==='webhook')content=`<h1>Receive new replies</h1><p class="page-description">Add this webhook in HeyReach so new replies arrive in your inbox automatically.</p><div class="notice success">${icon('check')}<div><strong>HeyReach connected</strong>${esc(state.setupName)} · 3 sender accounts · 4 campaigns</div></div><ol class="numbered-steps"><li>Open Settings → Webhooks in your HeyReach workspace.</li><li>Create a webhook and paste the URL below.</li></ol><div class="code-box"><code>https://hooks.aster.example/inbound/wh_demo_restaff</code>${ibtn('Copy webhook URL','copy-webhook','copy')}</div><ol class="numbered-steps" style="counter-reset:step 2"><li>Select the message reply event and save your webhook.</li></ol>${notice('The first event may arrive later','You can continue after saving the webhook. Its delivery status is available in Settings.','info')}${next('I’ve added the webhook','setup-next')}`;
if(step==='import')content=`<h1>Bring in your history</h1><p class="page-description">Choose how far back to import conversations. This can also be done later in Settings.</p><div class="field"><label>History window</label><div class="row" style="flex-wrap:wrap">${[7,14,30,90].map(n=>btn(n+' days','days:'+n,state.importDays===n?'primary':'')).join('')}</div></div><div class="card"><div class="row" style="align-items:flex-start;margin-bottom:18px">${icon('check')}<div><h3>Import messages and contacts</h3><p class="muted" style="margin-top:5px">Keep the original conversation history and senders.</p></div></div><div class="row" style="align-items:flex-start">${icon('check')}<div><h3>Classify the latest replies</h3><p class="muted" style="margin-top:5px">Organize conversations with labels such as Interested or Meeting Request.</p></div></div></div><p class="small muted" style="margin-top:18px;line-height:1.7">Historical replies won’t fill your Drafts queue. You can open any conversation and request a draft when you need one.</p><div class="wizard-footer">${btn('Skip for now','skip-history','ghost')}${btn('Import and continue','setup-next','primary','arrow')}</div>`;
if(step==='agent')content=`<h1>Set up your first agent</h1><p class="page-description">Tell your agent what your product does and how it should reply. Every message will need your approval.</p><div class="card" style="margin-top:18px">${field('Agent name','<input data-input="newAgentName" aria-label="First agent name" value="Restaff — Reply assistant">')}${field('Main objective','<div class="choice-grid"><button class="choice selected" data-action="setup-objective:call"><span class="radio"></span><span><strong>Book a call</strong><p>Answer questions and offer a demo.</p></span></button><button class="choice" data-action="setup-objective:custom"><span class="radio"></span><span><strong>Custom</strong><p>Define your own conversation goal.</p></span></button></div>')}</div>${notice('Finish the details in Agents','Add product Knowledge and test a reply before activating your agent. Conversations can sync while you do this.','info')}<div class="wizard-footer">${btn('Set up later','finish-setup-later','ghost')}${btn('Create agent','finish-setup','primary','arrow')}</div>`;
if(step==='done')content=`<div style="padding:12px 0"><span class="empty-icon" style="display:grid;place-items:center;background:#15271f;color:var(--green);width:52px;height:52px;border:1px solid #2b4839;border-radius:14px;margin-bottom:25px">${icon('check')}</span><h1>${esc(state.setupName)} is ready</h1><p class="page-description" style="margin-bottom:25px">Your workspace is connected. Finish your agent when you’re ready to start preparing replies.</p><div class="card"><div class="setting-row"><div><h3>HeyReach</h3><p>3 sender accounts connected</p></div>${badge('Connected','green')}</div><div class="setting-row"><div><h3>Incoming replies</h3><p>Webhook configured</p></div>${badge('Waiting for first event','amber')}</div><div class="setting-row"><div><h3>History</h3><p>${state.historySkipped?'You can import it later':`Last ${state.importDays} days`}</p></div>${badge(state.historySkipped?'Skipped':'Importing',state.historySkipped?'':'purple')}</div><div class="setting-row"><div><h3>Reply assistant</h3><p>Product Knowledge and test are next</p></div>${badge('Draft')}</div></div><div class="wizard-footer">${btn('Open conversations','setup-conversations','ghost')}${btn('Finish agent setup','setup-agent','primary','arrow')}</div></div>`;
return topbar('New workspace',btn('Save and exit','exit-setup','ghost small'))+`<div class="wizard-layout"><aside class="wizard-rail"><h2>${esc(state.setupName||'New workspace')}</h2><p>Connect your tools.<br>Make the inbox yours.</p>${[['name','Workspace'],['connect','HeyReach'],['webhook','Incoming replies'],['import','History'],['agent','Agent']].map(([id,label],i)=>`<button class="wizard-step ${step==='done'||i<index?'complete':i===index?'active':''}" data-action="scene:setup/${id}"><span class="step-number">${step==='done'||i<index?icon('check'):i+1}</span>${label}</button>`).join('')}</aside><div class="wizard-body"><div class="wizard-content">${content}</div></div></div>`}
const agents=[{name:'Re-engagement — Dormant 90d',initial:'R',color:'purple',drafts:312,status:'active',lang:'English'},{name:'Qualifier — SaaS Founders',initial:'Q',color:'teal',drafts:231,status:'paused',lang:'English'},{name:'Follow-up Engine — Agencies',initial:'F',color:'teal',drafts:203,status:'active',lang:'German'},{name:'Reply Handler — Fintech Q3',initial:'R',color:'purple',drafts:156,status:'active',lang:'English · Default'},{name:'Objection Handler — Enterprise',initial:'O',color:'amber',drafts:74,status:'active',lang:'English'},{name:'Meeting Booker — Recruiters',initial:'M',color:'pink',drafts:45,status:'paused',lang:'English'},{name:'Q&A Responder — Product Leads',initial:'Q',color:'teal',drafts:0,status:'draft',lang:'English'},{name:'Reply Handler — Logistics',initial:'R',color:'',drafts:0,status:'draft',lang:'Dutch'}];
function agentsScreen(){if(state.scene==='loading')return loadingList('Agents');if(state.scene==='error')return topbar('Agents')+blank('Agents could not be loaded','Your agent settings are saved. Try loading them again.','scene:agents/list','Try again','warning');if(state.scene==='empty')return topbar('Agents')+blank('Create your first agent','Give your agent a goal and product Knowledge. Test a reply before you activate it.','new-agent','Create agent','agent');if(state.scene!=='list')return agentEditor();const filtered=agents.filter(a=>(state.agentFilter==='all'||a.status===state.agentFilter)&&a.name.toLowerCase().includes(state.query.toLowerCase()));return topbar('',`<label class="search" style="width:240px">${icon('search')}<input data-input="query" aria-label="Search agents" placeholder="Search agents" value="${esc(state.query)}"><span class="shortcut">/</span></label><div class="tabs">${[['all','All',8],['active','Active',4],['paused','Paused',2],['draft','Draft',2]].map(([id,label,n])=>`<button class="tab ${state.agentFilter===id?'active':''}" data-action="agent-filter:${id}">${label}<span class="num">${n}</span></button>`).join('')}</div><div class="grow"></div><div class="toolbar">${ibtn('Grid view','agent-view:grid','grid',state.agentView==='grid'?'':'ghost')}${ibtn('List view','agent-view:list','list',state.agentView==='list'?'':'ghost')}${btn('New Agent','new-agent','primary','plus')}</div>`)+`<div class="content-scroll"><div class="${state.agentView==='grid'?'agent-grid':'agent-table'}">${filtered.map(a=>state.agentView==='grid'?`<article class="agent-card" data-action="open-agent:${a.name}" tabindex="0" role="button" aria-label="Open ${a.name}"><div class="row">${av(a.initial,a.color,'agent')}<div class="grow"><div class="agent-name">${a.name}</div><div class="agent-language">${a.status==='draft'?'Draft · ':''}${a.lang}</div></div></div><div class="agent-bottom"><div>${a.status==='draft'?'<div class="metric-label" style="margin-top:28px">Not published yet</div>':`<div class="metric">${a.drafts}</div><div class="metric-label">drafts generated</div>`}</div>${a.status==='draft'?'<span class="small" style="color:var(--accent-text)">Finish setup →</span>':`<span class="switch ${a.status==='active'?'on':''}" style="${a.status==='active'?'background:#29c89b;border-color:#29c89b':''}"></span>`}</div></article>`:`<button class="agent-table-row" data-action="open-agent:${a.name}"><span class="row">${av(a.initial,a.color,'agent')}<span class="agent-name">${a.name}</span></span><span class="muted small">${a.lang}</span><span class="small">${a.drafts||'—'} ${a.drafts?'drafts':''}</span><span class="switch ${a.status==='active'?'on':''}"></span></button>`).join('')}</div>${filtered.length?'':blank('No agents found','Try another name or change the status filter.','','','search')}</div>`}
function agentEditor(){let step=state.editorStep||'basics',body='';const next=()=>`<div class="editor-next">${btn('Continue','agent-next','ghost','arrow')}</div>`;
if(step==='basics')body=`<p class="page-description">What should this agent help you accomplish?</p>${field('Inbox Agent Name',`<input aria-label="Agent name" data-input="agentName" value="${esc(state.agentName)}">`)}${field('Main Objective',`<div class="choice-grid">${[['call','Book a call','Help interested leads book a conversation.'],['custom','Custom','Set a specific outcome for this agent.']].map(([id,l,c])=>`<button class="choice ${state.objective===id?'selected':''}" data-action="objective:${id}"><span class="radio"></span><span><strong>${l}</strong><p>${c}</p></span></button>`).join('')}</div>`)}${state.objective==='custom'?field('Custom Objective','<textarea aria-label="Custom objective" placeholder="Qualify the lead and route enterprise inquiries to sales…"></textarea>'):''}<div class="two-col">${field('Reply Language',`<div class="tabs">${['English','Russian','Match Lead'].map(l=>`<button class="tab ${state.language===l?'active':''}" data-action="language:${l}">${l}</button>`).join('')}</div>`)}${field('Reply Logic',`<div class="tabs">${['Only positive','All replies'].map(l=>`<button class="tab ${state.replyLogic===l?'active':''}" data-action="reply-logic:${l}">${l}</button>`).join('')}</div>`)}</div>${field('Custom Instructions <small>optional</small>','<textarea placeholder="Keep replies concise and conversational. Answer the question first. Ask no more than one question at a time." aria-label="Custom instructions"></textarea>','Extra guidance for how this agent should write its replies.')}${next()}`;
if(step==='knowledge')body=`<p class="page-description">What should this agent know about your company and offer?</p>${field('Company Name',`<input aria-label="Company name" value="${esc(state.workspace)}">`)}${field('Product & Offer','<textarea aria-label="Product and offer">Aster is an AI inbox for outbound teams. It organizes LinkedIn replies, drafts answers in the lead’s language and keeps a human in control of every send.</textarea>')}<div class="row between" style="margin-bottom:14px"><h3>FAQ</h3><span class="small muted">Approved answers to common questions</span></div>${[['How does pricing work?','Pricing depends on your team size and monthly reply volume. We can walk through the right plan on a short call.'],['Can the whole team review replies?','Yes. Team members can review drafts and reply from connected sender accounts in a shared workspace.'],...(state.extraFaq?[['','']]:[])].map(([q,a],i)=>`<div class="card" style="margin-bottom:12px;padding:17px"><div class="row between" style="margin-bottom:10px"><span class="small muted">Q&A ${i+1}</span>${ibtn('Delete Q&A '+(i+1),'delete-faq:'+i,'trash')}</div><input placeholder="Question" aria-label="Question ${i+1}" value="${q}" style="width:100%;margin-bottom:10px"><textarea placeholder="Approved answer" aria-label="Approved answer ${i+1}" style="min-height:83px">${a}</textarea></div>`).join('')}${btn('Add Q&A','add-faq','ghost','plus','style="width:100%;border:1px dashed var(--line)"')}<div style="margin-top:20px">${notice('When Knowledge is not enough','The conversation moves to Needs input in Drafts so your team can provide an answer.','info')}</div>${next()}`;
if(step==='followups')body=`<p class="page-description">What should happen when a lead stops replying?</p><div class="row" style="margin-bottom:25px">${toggle('Enable follow-ups','followups',state.followups)}<h3>Enable follow-ups</h3></div>${state.followups?[1,2].map((n)=>`<div class="card" style="margin-bottom:16px"><div class="row between" style="margin-bottom:18px"><h3>Follow-up ${n}</h3>${ibtn('Remove follow-up '+n,'remove-followup:'+n,'trash')}</div><div class="row" style="margin-bottom:17px"><span class="small muted">Prepare after</span><input type="number" value="${n*2}" min="1" max="30" style="width:65px" aria-label="Follow-up ${n} delay"><span>days without a reply</span></div><textarea aria-label="Follow-up ${n} instructions">${n===1?'Briefly follow up without repeating the full pitch. Reference the last question and offer a short call.':'Share one relevant example. Keep the message to three sentences.'}</textarea></div>`).join('')+btn('Add follow-up','add-followup','ghost','plus','style="width:100%;border:1px dashed var(--line)"'):notice('Follow-ups are off','This agent prepares replies only when a new message arrives. You can turn follow-ups on later.','info')}<div style="margin-top:20px">${notice('Every follow-up needs approval','Prepared follow-ups appear in Drafts. Nothing is sent automatically.','info')}</div>${next()}`;
if(step==='test')body=`<div class="row between"><p class="page-description" style="margin:0">Chat as a lead. Nothing will be sent.</p>${btn('New test chat','new-test','small','refresh')}</div><div class="test-presets" style="margin-top:22px">${['Interested','Product question','Meeting request','Not interested','Knowledge gap'].map(t=>btn(t,'test-preset:'+t,'ghost small','','style="border-color:var(--line);border-radius:20px"')).join('')}</div><div class="test-chat">${state.testReply?`<div class="message outbound"><div class="message-meta"><span>You as lead</span></div><div class="bubble">${esc(state.testMessage||state.testLead)}</div></div>${state.testGap?notice('Needs input','The agent has no approved information about data retention. Add an answer in Knowledge before replying.',''): `<div class="message"><div class="message-meta"><span>Agent</span></div><div class="bubble">${state.testReply}</div></div>`}<button class="link-btn small" data-action="test-details">Details ${icon('down')}</button>${state.testDetails?'<div class="card" style="padding:14px;margin-top:12px"><div class="details-row"><span>Language</span><span>English</span></div><div class="details-row"><span>Intent</span><span>Information Request</span></div><div class="details-row"><span>Knowledge</span><span>'+(state.testGap?'Needs input':'Sufficient')+'</span></div><div class="details-row"><span>Decision</span><span>'+(state.testGap?'Ask your team':'Prepare a reply')+'</span></div></div>':''}`:blank('Try a conversation','Write as a lead or choose one of the examples above.','','','chat')}</div><div class="row"><input class="grow" data-input="testLead" aria-label="Write as a lead" placeholder="Write as a lead…" value="${esc(state.testLead||'')}">${ibtn('Send test message','test-send','send','primary')}</div>${next()}`;
if(step==='launch')body=`<p class="page-description">Where should this agent prepare replies?</p><h3 style="margin-bottom:14px">Assignment</h3><button class="choice ${state.agentDefault!==false?'selected':''}" data-action="toggle:agentDefault"><span class="radio"></span><span><strong>Workspace default</strong><p>Use this agent for campaigns without another agent assigned.</p></span></button><div class="divider"></div><h3 style="margin-bottom:14px">Selected campaigns</h3>${[['SaaS Leaders — Q3','412 leads'],['Founder Network','268 leads'],['Agency Leaders','190 leads']].map(([n,c],i)=>`<label class="choice" style="margin-bottom:9px;align-items:center"><input type="checkbox" ${i===0?'checked':''}><span class="grow"><strong style="margin:0">${n}</strong></span><span class="small muted">${c}</span></label>`).join('')}<div style="margin-top:24px">${notice('You review every reply','After activation, new eligible replies generate drafts for your team. No messages are sent automatically.','info')}</div><div class="editor-next">${btn(state.agentIsNew?'Activate agent':'Save assignment','launch-agent','primary','play')}</div>`;
return `<header class="topbar">${ibtn('Back to Agents','nav:agents','back')}<span class="avatar agent purple" style="width:32px;height:32px">${esc(state.agentName[0]||'A')}</span><div class="grow"><h2 style="font-size:14px">${esc(state.agentName)}</h2><p class="tiny muted">${state.agentIsNew?'Draft · setup in progress':'Active'}</p></div>${!state.agentIsNew?toggle('Agent active','agentActive',state.agentActive!==false):''}${btn('Save changes','save-agent','small')}</header><div class="editor-tabs"><nav class="tabs" aria-label="Agent setup steps">${[['basics','Basics'],['knowledge','Knowledge'],['followups','Follow-ups'],['test','Test'],['launch','Launch']].map(([id,l],i)=>`<button class="tab ${step===id?'active':''}" data-action="agent-step:${id}"><span class="tiny muted" style="margin-right:6px">0${i+1}</span>${l}</button>`).join('')}</nav></div><div class="content-scroll"><div class="editor-content">${body}</div></div>`}
function conversationsScreen(){if(state.scene==='loading')return loadingList('Conversations');if(state.scene==='error')return topbar('Conversations')+blank('Conversations could not be loaded','Try again to see your latest messages.','scene:conversations/list','Try again','warning');if(state.scene==='thread')return topbar('Conversations',btn('Back to list','scene:conversations/list','ghost small','back'))+`<div class="draft-layout mobile-thread ${state.details?'':'details-closed'}" style="grid-template-columns:minmax(340px,1fr) ${state.details?'264px':''}">${thread(selected())}${state.details?contextPanel(selected()):''}</div>`;if(state.scene==='empty')return topbar('Conversations')+blank('Your inbox starts here','New replies will appear automatically. You can also import existing conversations from HeyReach.','scene:settings/import','Import conversations','chat');const noResults=state.scene==='no-results';const filtered=items.filter(x=>(!state.query||(x.name+' '+x.company).toLowerCase().includes(state.query.toLowerCase()))&&(!state.convFilter||state.convFilter==='All'||x.labels.includes(state.convFilter)));return topbar('',`<label class="search grow" style="height:36px">${icon('search')}<input aria-label="Search conversations" data-input="query" placeholder="Search conversations…" value="${esc(noResults?'No matching person':state.query)}"><span class="shortcut">⌘ K</span></label>${btn('Filters','filters','','filter')}${btn('Export','export','','download')}`)+`<div class="content-scroll" style="padding-top:12px"><div class="row filter-bar" style="margin-bottom:12px">${['All','Interested','Meeting Request','Information Request'].map(l=>btn(l==='Meeting Request'?'Meetings':l==='Information Request'?'Info requests':l,'conv-filter:'+l,(!state.convFilter&&l==='All')||state.convFilter===l?'small':'ghost small')).join('')}</div>${noResults?blank('No conversations found','Try another name, company or keyword.','clear-conversation-search','Clear search','search'):`<div class="conversation-list">${filtered.map((x,i)=>`<button class="conversation-row ${i<2?'unread':''}" data-action="conversation:${x.id}">${av(x.initials,x.color)}<span><strong>${x.name}</strong><small>${x.company}</small></span><span class="row" style="gap:4px;flex-wrap:wrap">${labels(x.labels)}</span><span class="snippet">${x.incoming}</span><time>${x.time}</time></button>`).join('')}</div>${!filtered.length?blank('No conversations found','Try another name or change the active filter.','','','search'):''}`}</div>`}
const screens=[['Drafts',[['drafts/ready','Ready draft'],['drafts/edit','Editing a draft'],['drafts/redraft','Redraft with instructions'],['drafts/manual','Manual reply'],['drafts/needs-input','Knowledge gap'],['drafts/stale','New inbound reply'],['drafts/generating','Generating a draft'],['drafts/sending','Sending'],['drafts/send-error','Send rejected'],['drafts/unknown','Send result unknown'],['drafts/snoozed','Snoozed queue'],['drafts/empty','Queue cleared'],['drafts/loading','Loading'],['drafts/error','Queue unavailable']]],['Workspace setup',[['setup/name','Workspace name'],['setup/connect','Connect HeyReach'],['setup/key-error','Invalid API key'],['setup/webhook','Set up webhook'],['setup/import','Import history'],['setup/agent','Choose an agent'],['setup/done','Workspace ready']]],['Settings',[['settings/general','General'],['settings/connection','HeyReach connected'],['settings/disconnected','HeyReach disconnected'],['settings/key-error','Connection needs attention'],['settings/webhook-waiting','Waiting for first event'],['settings/import','Historical import'],['settings/import-running','Import in progress'],['settings/import-done','Import complete'],['settings/import-error','Import interrupted'],['settings/members','Members'],['settings/preferences','Preferences']]],['Existing screens',[['conversations/list','Conversations'],['conversations/thread','Conversation detail'],['conversations/empty','No conversations'],['conversations/no-results','Search has no results'],['agents/list','Agents'],['agents/empty','No agents'],['agents/basics','Agent basics'],['agents/knowledge','Agent Knowledge'],['agents/followups','Agent follow-ups'],['agents/test','Test an agent'],['agents/launch','Launch an agent'],['agents/loading','Agents loading'],['agents/error','Agents unavailable'],['conversations/loading','Conversations loading'],['conversations/error','Conversations unavailable']]],['Access',[['auth/login','Sign in'],['auth/reset','Reset password'],['auth/reset-sent','Password link sent'],['auth/invite','Accept invitation'],['auth/no-access','Workspace access denied']]]];
function renderOverlay(){let html='';if(state.catalog)html=`<aside class="catalog" aria-label="Design screen catalogue"><div class="catalog-header"><div class="row between"><h2>Screen catalogue</h2>${ibtn('Close catalogue','close-overlay','close')}</div><p>Interactive design proposal. All data is fictional. No messages, invitations or API requests are sent.</p></div><div class="catalog-list">${screens.map(([group,list])=>`<div class="catalog-section">${group}</div>${list.map(([route,label],i)=>`<button class="catalog-item ${state.page+'/'+state.scene===route?'active':''}" data-action="preview:${route}">${label}<span>${String(i+1).padStart(2,'0')}</span></button>`).join('')}`).join('')}<div class="divider"></div>${btn('Reset demo','reset','ghost','refresh')}</div></aside>`;
if(state.modal==='workspaces')html=`<div class="modal-backdrop" data-action="close-backdrop"><div role="dialog" aria-modal="true" aria-label="${esc(state.modal||'Dialog')}" class="modal" style="width:360px"><div class="row between"><h2>Workspaces</h2>${ibtn('Close','close-overlay','close')}</div>${['Aster','Restaff'].map(n=>`<button class="menu-item" data-action="workspace:${n}"><span class="brandmark">${n==='Aster'?'AS':'RE'}</span><span class="grow">${n}</span>${n===state.workspace?icon('check'):''}</button>`).join('')}<div class="divider"></div>${btn('Create workspace','nav:setup','primary','plus', 'style="width:100%"')}</div></div>`;
if(['draft-more','snooze','reject','profile'].includes(state.modal)){const contents={
 'draft-more':`<h2>Draft actions</h2><button class="menu-item" data-action="snooze">${icon('clock')}Snooze</button><button class="menu-item" data-action="reject">${icon('trash')}Dismiss draft</button><button class="menu-item" data-action="open-conversation">${icon('chat')}Open conversation</button>`,
 snooze:`<h2>Snooze this draft</h2><p>It will return to your review queue at the selected time. A new reply brings it back sooner.</p>${['Later today','Tomorrow morning','Next Monday'].map(x=>`<button class="menu-item" data-action="snooze-set:${x}">${icon('clock')}${x}<span class="grow"></span>${icon('chevron')}</button>`).join('')}`,
 reject:`<h2>Dismiss this draft?</h2><p>The draft will leave your review queue. The conversation and its history will remain in Conversations.</p><div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Dismiss draft','reject-confirm','danger')}</div>`,
 profile:`<h2>Ivan Leushin</h2><p>ivan@example.com · Workspace owner</p><button class="menu-item" data-action="scene:settings/preferences">${icon('settings')}Preferences</button><button class="menu-item" data-action="catalog">${icon('layers')}Design screen catalogue</button>`};html=`<div class="modal-backdrop" data-action="close-backdrop"><div role="dialog" aria-modal="true" aria-label="${esc(state.modal||'Dialog')}" class="modal"><div style="float:right">${ibtn('Close','close-overlay','close')}</div>${contents[state.modal]}</div></div>`}
if(state.modal&&['invite','disconnect','replace-key','webhook-help','workspace-icon','archive-workspace','member-actions','filters','export','delete-faq'].includes(state.modal)){
const bodies={
invite:`<h2>Invite a teammate</h2><p>Give someone access to ${esc(state.workspace)}. Their access applies only to this workspace.</p>${field('Email address','<input id="invite-email" type="email" required placeholder="teammate@company.com" aria-label="Teammate email">')}${field('Role','<select aria-label="Invitation role"><option>Member — review drafts and send replies</option><option>Admin — manage agents and connections</option></select>')}<div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Send invitation','invite-confirm','primary')}</div>`,
disconnect:`<h2>Disconnect HeyReach?</h2><p>New messages will stop syncing and sending will be paused. Existing conversations, drafts and agent settings will stay in your workspace.</p><div class="modal-actions">${btn('Keep connected','close-overlay')}${btn('Disconnect','disconnect-confirm','danger')}</div>`,
'replace-key':`<h2>Replace API key</h2><p>Use a new key from the same HeyReach workspace. We’ll verify it before replacing the current key.</p>${field('New API key','<input type="password" value="hr_demo_replacement" aria-label="New API key">')}<div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Verify and replace','replace-confirm','primary')}</div>`,
'webhook-help':`<h2>Webhook setup</h2><p>Configure this in the HeyReach workspace connected to ${esc(state.workspace)}.</p><ol class="numbered-steps"><li>Open Settings → Webhooks in HeyReach.</li><li>Create a webhook and paste the URL below.</li><li>Select the message reply event and save.</li></ol><div class="code-box"><code>https://hooks.aster.example/inbound/wh_demo</code>${ibtn('Copy webhook URL','copy-webhook','copy')}</div><p class="small muted">Delivery is confirmed when the first event arrives. No new reply yet is an expected waiting state.</p><div class="modal-actions">${btn('Done','close-overlay','primary')}</div>`,
'workspace-icon':`<h2>Workspace icon</h2><p>Choose a color for your workspace initials.</p><div class="row" style="gap:12px">${['#8066f6','#2b997c','#4379b4','#b47843','#a0528c'].map(c=>`<button data-action="icon-color:${c}" aria-label="Choose ${c}" style="width:42px;height:42px;background:${c};border-radius:10px;font-weight:600">${state.workspace.slice(0,2).toUpperCase()}</button>`).join('')}</div><div class="modal-actions">${btn('Cancel','close-overlay')}</div>`,
'archive-workspace':`<h2>Archive ${esc(state.workspace)}?</h2><p>Message sync and AI drafting will stop. The workspace’s history will be preserved and can be restored later.</p><div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Archive workspace','archive-confirm','danger')}</div>`,
'member-actions':`<h2>Alex Carter</h2><p>alex@example.com · Member</p>${notice('Workspace access','Removing this member revokes their access to this workspace only.','info')}<div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Remove member','remove-member','danger')}</div>`,
filters:`<h2>Filter conversations</h2><p>Find conversations that need your attention.</p>${field('Labels','<select id="filter-label" aria-label="Filter labels"><option>All</option><option>Interested</option><option>Information Request</option><option>Meeting Request</option><option>Referral</option></select>')}${field('Campaign','<select aria-label="Filter campaign"><option>All campaigns</option><option>SaaS Leaders — Q3</option><option>Founder Network</option><option>Agency Leaders</option></select>')}<div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Apply filters','apply-filters','primary')}</div>`,
export:`<h2>Export conversations</h2><p>Download the current conversation list as a CSV file.</p><div class="choice selected"><span class="radio"></span><span><strong>Current view</strong><p>Contact name, company, labels and latest activity.</p></span></div><div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Export CSV','export-confirm','primary','download')}</div>`,
'delete-faq':`<h2>Remove this Q&A?</h2><p>The agent will stop using this answer after you save the updated Knowledge.</p><div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Remove Q&A','delete-faq-confirm','danger')}</div>`
};html=`<div class="modal-backdrop" data-action="close-backdrop"><div role="dialog" aria-modal="true" aria-label="${esc(state.modal||'Dialog')}" class="modal"><div style="float:right">${ibtn('Close','close-overlay','close')}</div>${bodies[state.modal]}</div></div>`;
}
$('#overlay-root').innerHTML=html;const dialog=$('.modal');if(dialog)(dialog.querySelector('input:not([type=checkbox])')||dialog.querySelector('button'))?.focus();}
function removeFromQueue(status){const p=selected();p.status=status;const next=items.find(x=>x.status===state.queue);if(next){state.selected=next.id;state.draftText=next.draft;state.mode='draft'}else state.mobileThread=false;state.modal=null;render()}
function handleAction(action){const [kind,...rest]=action.split(':');const value=rest.join(':');switch(kind){case'noop':return;case'auth-login':{const form=$('#auth-form');if(form&&!form.reportValidity())return;navigate('drafts/ready');toast('Signed in · design preview');return;}case'auth-reset':navigate('auth/reset-sent');return;case'auth-accept':state.workspace='Restaff';navigate('drafts/ready');toast('Joined Restaff · design preview');return;case'nav':navigate(value+'/'+({drafts:'ready',settings:'general',setup:'name',agents:'list',conversations:'list'}[value]));return;case'preview':items=structuredClone(fixtures);state.sent=[];state.answer='';state.draftText='';state.testReply='';navigate(value);return;case'scene':navigate(value);return;case'catalog':state.modal=null;state.catalog=true;renderOverlay();return;case'close-overlay':state.modal=null;state.catalog=false;renderOverlay();return;case'close-backdrop':return;case'workspaces':case'profile':case'draft-more':case'snooze':case'reject':state.modal=kind;state.catalog=false;renderOverlay();return;case'workspace':state.workspace=value;state.modal=null;render();toast('Switched to '+value);return;case'queue':state.queue=value;state.scene=value==='needs'?'needs-input':value==='later'?'snoozed':'ready';state.mode='draft';state.mobileThread=false;state.draftText='';render();return;case'select':state.selected=value;state.draftText=selected().draft;state.mode='draft';state.mobileThread=true;render();return;case'toggle-details':state.details=!state.details;render();return;case'back-queue':state.mobileThread=false;render();return;case'manual':state.mode='manual';render();return;case'edit':state.mode='edit';state.draftText=state.draftText||selected().draft;render();return;case'redraft':state.mode='redraft';render();return;case'cancel-edit':case'cancel-generation':clearTimeout(state.generationTimer);state.mode='draft';state.redraftText='';state.draftText=selected().draft;render();return;case'generate':case'redraft-generate':case'answer-generate':case'update-draft':{if(kind==='answer-generate'){selected().draft=state.answer;selected().status='ready';state.queue='ready';if(state.remember)toast('Answer added to the agent’s Knowledge')}state.mode='generating';state.scene='ready';render();state.generationTimer=setTimeout(()=>{state.draftText=kind==='redraft-generate'?`Hi ${selected().name.split(' ')[0]} — happy to help. Would a short demo be useful to walk through this together?`:kind==='answer-generate'?`Hi ${selected().name.split(' ')[0]} — ${state.answer}`:selected().draft;state.mode='draft';render()},1100);return;}case'send':{const body=state.mode==='manual'?state.manualText:state.draftText||selected().draft;if(!body.trim()||state.scene==='stale')return;state.sendBody=body;state.mode='sending';state.scene='ready';render();state.sendTimer=setTimeout(()=>{state.sent.push({person:selected().id,body});state.manualText='';if(state.page==='drafts'){removeFromQueue('sent');toast('Message sent · next draft opened')}else{state.mode='manual';render();toast('Message sent')}},800);return;}case'check-send':state.sent.push({person:selected().id,body:selected().draft});state.scene='ready';removeFromQueue('sent');toast('Message found · marked as sent');return;case'snooze-set':selected().time=value;removeFromQueue('later');toast('Snoozed until '+value.toLowerCase());return;case'reject-confirm':removeFromQueue('dismissed');toast('Draft dismissed · conversation preserved');return;case'open-conversation':navigate('conversations/thread');return;case'agent-open':navigate('agents/basics');return;case'linkedin':toast('External profile link · disabled in this design preview');return;case'refresh-drafts':toast('Queue is up to date');return;case'retry-drafts':navigate('drafts/ready');return;case'reset':items=structuredClone(fixtures);state.sent=[];state.answer='';state.notes='';navigate('drafts/ready');toast('Demo reset');return;default:handleExtendedAction(kind,value)}}
function loadingList(title){return topbar(title)+`<div class="content-scroll"><div class="skeleton short" style="margin-bottom:28px"></div>${Array.from({length:7},()=>'<div class="row skeleton-box"><div class="avatar" style="background:#202027;border:0"></div><div class="grow"><div class="skeleton medium"></div><div class="skeleton short"></div></div></div>').join('')}</div>`}
function authScreen(){let content='';if(state.scene==='login')content=`<h1>Welcome back</h1><p class="page-description">Sign in to your workspace.</p><form id="auth-form" onsubmit="return false">${field('Email address','<input type="email" required value="ivan@example.com" autocomplete="username" aria-label="Sign-in email">')}${field('Password','<input type="password" required value="demo-password" autocomplete="current-password" aria-label="Password">')}<div style="text-align:right;margin:-10px 0 23px"><button class="link-btn small" data-action="scene:auth/reset">Forgot password?</button></div>${btn('Sign in','auth-login','primary','','style="width:100%"')}</form><p class="small muted" style="margin-top:24px;text-align:center">Access is managed by your workspace owner.</p>`;
if(state.scene==='reset')content=`<h1>Reset your password</h1><p class="page-description">We’ll send you a link to choose a new password.</p>${field('Email address','<input type="email" value="ivan@example.com" aria-label="Reset email">')}${btn('Send reset link','auth-reset','primary')}<div style="text-align:center;margin-top:20px">${btn('Back to sign in','scene:auth/login','ghost small','back')}</div>`;
if(state.scene==='reset-sent')content=`<div class="empty-icon" style="color:var(--accent-text);margin-bottom:20px">${icon('mail')}</div><h1>Check your email</h1><p class="page-description">If an account exists for this email, you’ll receive a password reset link shortly.</p>${btn('Back to sign in','scene:auth/login','primary')}`;
if(state.scene==='invite')content=`<span class="brandmark" style="width:44px;height:44px;font-size:14px;margin-bottom:22px">RE</span><h1>Join Restaff</h1><p class="page-description">Ivan invited you to review drafts and manage conversations in Restaff.</p><div class="card" style="margin-bottom:22px"><div class="details-row"><span>Workspace</span><span>Restaff</span></div><div class="details-row"><span>Your role</span><span>Member</span></div><div class="details-row"><span>Email</span><span>alex@example.com</span></div></div>${btn('Accept invitation','auth-accept','primary')}<p class="small muted" style="text-align:center;margin-top:20px">You’re signed in as alex@example.com</p>`;
if(state.scene==='no-access')content=`<div style="color:var(--muted);margin-bottom:20px">${icon('shield')}</div><h1>Workspace access needed</h1><p class="page-description">Your account doesn’t have access to this workspace. Ask its owner to invite you, or choose another workspace.</p>${btn('Choose workspace','workspaces','primary')}<div style="text-align:center;margin-top:20px">${btn('Use another account','scene:auth/login','ghost small')}</div>`;
return `<div class="auth-page"><div class="auth-brand"><span class="brandmark">AS</span>Aster</div><div class="auth-center"><div class="auth-card">${content}</div></div><div class="auth-footer"><button data-action="catalog">${icon('layers')} Design preview</button></div></div>`}
function handleExtendedAction(kind,value){switch(kind){
case'days':state.importDays=Number(value);render();break;
case'toggle':{const defaults=['autoNext','defaultDetails','shortcuts','agentDefault','agentActive'];state[value]=!(state[value]===undefined?defaults.includes(value):state[value]);render();if(state.page==='settings')toast('Preference saved');break;}
case'save-settings':if(state.workspaceName?.trim())state.workspace=state.workspaceName.trim();render();toast('Workspace settings saved');break;
case'workspace-icon':state.modal='workspace-icon';renderOverlay();break;
case'icon-color':state.brandColor=value;state.modal=null;render();document.querySelectorAll('.sidebar .brandmark').forEach(e=>e.style.background=value);toast('Workspace icon updated');break;
case'archive-workspace':case'invite':case'member-actions':case'disconnect':case'replace-key':case'webhook-help':case'filters':case'export':state.modal=kind;renderOverlay();break;
case'archive-confirm':state.modal=null;toast('Workspace archived in this preview');state.workspace='Aster';navigate('drafts/ready');break;
case'copy-webhook':toast('Demo webhook URL copied');navigator.clipboard?.writeText('https://hooks.aster.example/inbound/wh_demo_restaff').catch(()=>{});break;
case'test-connection':toast('Connection verified · 3 senders and 4 campaigns found');break;
case'simulate-event':navigate('settings/connection');toast('A test event was received');break;
case'verify-reconnect':navigate('settings/connection');toast('HeyReach reconnected · message sync resumed');break;
case'connect-existing':state.setupName=state.workspace;navigate('setup/connect');break;
case'disconnect-confirm':navigate('settings/disconnected');toast('Disconnected · conversations and drafts preserved');break;
case'replace-confirm':state.modal=null;render();toast('API key replaced · connection verified');break;
case'start-import':navigate('settings/import-running');setTimeout(()=>{if(state.page==='settings'&&state.scene==='import-running'){navigate('settings/import-done');toast('History imported and classified')}},4500);break;
case'pause-import':navigate('settings/import-error');break;
case'resume-import':navigate('settings/import-running');toast('Connection restored · import resumed');break;
case'complete-import':navigate('settings/import-done');break;
case'invite-confirm':{const input=$('#invite-email');const email=input?.value.trim();if(!email||!input.checkValidity()){input?.reportValidity();return;}state.invited=email;state.modal=null;render();toast('Invitation created · preview only');break;}
case'revoke-invite':state.invited=null;render();toast('Invitation revoked');break;
case'remove-member':state.modal=null;render();document.querySelector('[data-action="member-actions"]')?.closest('.account-line')?.remove();toast('Member removed from this workspace');break;
case'setup-next':{const steps=['name','connect','webhook','import','agent'];if(state.setupStep==='name'&&!state.setupName.trim()){toast('Enter a workspace name');return;}if(state.setupStep==='import')state.historySkipped=false;navigate('setup/'+steps[Math.min(steps.indexOf(state.setupStep)+1,4)]);break;}
case'setup-back':{const steps=['name','connect','webhook','import','agent'];navigate('setup/'+steps[Math.max(0,steps.indexOf(state.setupStep)-1)]);break;}
case'verify-key':if(!state.setupKey.trim()){navigate('setup/key-error');break;}navigate('setup/webhook');toast('HeyReach workspace verified');break;
case'skip-history':state.historySkipped=true;navigate('setup/agent');break;
case'setup-objective':state.setupObjective=value;render();document.querySelectorAll('[data-action^="setup-objective:"]').forEach(b=>b.classList.toggle('selected',b.dataset.action.endsWith(value)));break;
case'finish-setup':case'finish-setup-later':state.workspace=state.setupName;state.agentIsNew=true;state.agentName=state.newAgentName||state.setupName+' — Reply assistant';navigate('setup/done');break;
case'setup-conversations':navigate('conversations/empty');break;
case'setup-agent':state.agentIsNew=true;navigate('agents/knowledge');break;
case'exit-setup':navigate('settings/connection');toast('Setup progress saved');break;
case'agent-filter':state.agentFilter=value;render();break;
case'agent-view':state.agentView=value;render();break;
case'new-agent':state.agentIsNew=true;state.agentName='Untitled Agent';navigate('agents/basics');break;
case'open-agent':state.agentIsNew=value.includes('Logistics')||value.includes('Product Leads');state.agentName=value;navigate('agents/basics');break;
case'agent-step':navigate('agents/'+value);break;
case'agent-next':{const steps=['basics','knowledge','followups','test','launch'];navigate('agents/'+steps[Math.min(steps.indexOf(state.editorStep)+1,4)]);break;}
case'objective':state.objective=value;render();break;
case'language':state.language=value;render();break;
case'reply-logic':state.replyLogic=value;render();break;
case'save-agent':if(!state.agentName.trim()){toast('Enter an agent name');return;}toast('Agent changes saved');break;
case'launch-agent':state.agentIsNew=false;state.agentActive=true;render();toast('Agent activated · new replies will appear in Drafts');break;
case'add-faq':state.extraFaq=true;render();break;
case'delete-faq':state.modal='delete-faq';state.deleteFaq=Number(value);renderOverlay();break;
case'delete-faq-confirm':state.extraFaq=false;state.modal=null;render();toast('Q&A removed in this preview');break;
case'add-followup':toast('Two follow-up examples are shown in this design');break;
case'remove-followup':state.followups=false;render();toast('Follow-ups turned off');break;
case'test-preset':state.testLead=({'Interested':'This sounds interesting. Could you tell me more?','Product question':'Can my whole team review replies in the same workspace?','Meeting request':'Could we book a short demo next week?','Not interested':'Thanks, but this is not a priority right now.','Knowledge gap':'How long do you retain our data, and can you send a security report?'}[value]);state.testPreset=value;render();break;
case'test-send':if(!state.testLead?.trim()){toast('Write a message or select an example');return;}state.testMessage=state.testLead;state.testLead='';state.testGap=state.testPreset==='Knowledge gap';state.testReply=state.testPreset==='Not interested'?'Understood — thanks for letting me know.':state.testPreset==='Meeting request'?'Happy to arrange a short demo. Which day next week works best for you?':'Yes — your team can review drafts and reply from connected sender accounts in a shared workspace. Would you like to see the workflow in a short demo?';render();break;
case'new-test':state.testLead='';state.testReply='';state.testDetails=false;state.testPreset='';render();break;
case'test-details':state.testDetails=!state.testDetails;render();break;
case'conv-filter':state.convFilter=value;render();break;
case'conversation':state.selected=value;state.draftText=selected().draft;navigate('conversations/thread');break;
case'clear-conversation-search':state.query='';state.convFilter='All';navigate('conversations/list');break;
case'apply-filters':state.convFilter=$('#filter-label')?.value||'All';state.modal=null;render();break;
case'export-confirm':state.modal=null;render();toast('CSV export previewed · no real data exported');break;
default:toast('Preview action: '+kind);
}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;if(target.dataset.action==='close-backdrop'){if(e.target===target){state.modal=null;renderOverlay()}return}handleAction(target.dataset.action)});
document.addEventListener('input',e=>{const key=e.target.dataset.input;if(!key)return;state[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='query'){const caret=e.target.selectionStart;render();const input=$('[data-input="query"]');input?.focus();input?.setSelectionRange(caret,caret)}else if(['redraftText','manualText','answer'].includes(key)){const b=$('[data-action="'+({redraftText:'redraft-generate',manualText:'send',answer:'answer-generate'}[key])+'"]');if(b)b.disabled=!state[key].trim()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button][data-action]')){e.preventDefault();e.target.click();return;}const dialog=$('.modal,.catalog');if(e.key==='Tab'&&dialog){const focusable=[...dialog.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(e.key==='Escape'){state.modal=null;state.catalog=false;renderOverlay()}if(state.shortcuts!==false&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'&&['drafts','conversations'].includes(state.page)&&!state.modal&&!state.catalog){const b=$('[data-action="send"]');if(b&&!b.disabled){e.preventDefault();handleAction('send')}}});
window.addEventListener('hashchange',()=>{clearTimeout(state.sendTimer);clearTimeout(state.generationTimer);readRoute();render()});
readRoute();render();
